import{z as d,x as o,o as r,c as B,q as i,j as E,D as a,d as n,s,S as A,b as l}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"Ring / Tree allreduce","description":"","frontmatter":{"title":"Ring / Tree allreduce","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ring-tree-allreduce.md","filePath":"llm/ring-tree-allreduce.md","lastUpdated":1791413859000}'),c={name:"llm/ring-tree-allreduce.md"};function p(u,e,m,h,g,C){const t=o("Mermaid");return r(),B("div",null,[e[2]||(e[2]=i('<h1 id="ring-tree-allreduce" tabindex="-1">Ring / Tree allreduce <a class="header-anchor" href="#ring-tree-allreduce" aria-label="Permalink to &quot;Ring / Tree allreduce&quot;">​</a></h1><div class="epigraph"><p>同一条 All-Reduce，可以沿环把体积摊成 $2(N-1)$ 步小块，也可以沿树把延迟收成对数跳。选哪张图，取决于消息有多大、拓扑有多对称。</p><footer>—— 对照带宽最优环算法与 NCCL 的 Ring / Tree；集群侧总图见预训练通信</footer></div><p><a href="/llm/on-device-speculative">端侧投机</a> 把延迟墙收在单机草稿。本课打开新课「通信与集群」：多卡一步里真正同步的，是梯度或分片参数，原语几乎总是 All-Reduce。<a href="/llm/pretrain-comm">预训练通信</a> 已经把库、<a href="/llm/nvlink">NVLink</a>、跨节点三层画在一张图上；缺口是 <strong>算法本身</strong>：环与树搬的字节不同、对拓扑的对称性要求不同。后课默认你会：All-Reduce 可以拆成环上的流水，也可以拆成树上的归约加广播，有效带宽不是网卡标称。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(N\\) 张卡各持一份同形张量，要得到逐元素求和（或平均）。朴素做法是每张卡把整份发给根再广播回来，根的注入带宽是 \\(N-1\\) 倍体积，立刻成为墙。数据并行的梯度 All-Reduce 每步都要做这一次，体积等于参数量；张量并行的层内 All-Reduce 更短、更频繁。问题不是「要不要同步」，而是：<strong>同步的调度把带宽瓶颈放在谁身上</strong>。</p><p><span class="marginnote">术语翻译：All-Reduce 就是「大家的数加到一起，然后每人拿到同一份和」。8 张卡各有一个梯度向量，走完一次 All-Reduce，8 张卡上都变成这 8 个向量的平均——求和与分发一步完成，不需要先选个根再广播。</span></p><p>环的承诺是带宽最优：每张卡只跟左右邻居说话，每条边负载相同。树的承诺是延迟更短：跳数 \\(O(\\log N)\\)，但根附近的边更忙，小消息时启动开销主导。NCCL 在同一进程组里两种都会用，按消息大小切换。<a href="/llm/nvlink">NVLink</a> 域内环很香，因为链路对称；跨节点若环绕过订阅不足的轨，最慢那一跳拖住整步。</p><p><span class="marginnote">Patarasuk 与 Yuan 给出过带宽最优 All-Reduce 的下界：每卡至少要发出并收回约 \\(2\\frac{N-1}{N}\\) 倍本地体积。环达到这个下界；树在大消息上通常达不到，除非层次化到「每节点一份」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环 All-Reduce 标准分解是：先做 <strong>reduce-scatter</strong>（每卡留下 \\(1/N\\) 的归约结果），再做 <strong>all-gather</strong>（把各片拼回全量）。实现上把张量切成 \\(N\\) 块，沿环同时转：第 \\(k\\) 步，卡 \\(i\\) 把当前块发给 \\(i+1\\)，并与从 \\(i-1\\) 收到的块做本地归约。两轮各 \\(N-1\\) 步之后，每卡持有完整和。流水使链路几乎一直满；代价是步数随 \\(N\\) 线性涨，小消息时 \\(\\alpha\\) 项打死。</p><p>树 All-Reduce 是归约树加广播树（可以是同一棵，也可以是双二叉树）。跳数对数，适合延迟区。跨节点常见层次化：节点内先用 <a href="/llm/nvlink">NVLink</a> 收成每节点一份，再在节点间走树或环，最后节点内展开。这样跨节点体积从「每 GPU 一份」变成「每节点一份」，正是 <a href="/llm/pretrain-comm">预训练通信</a> 写过的层次化，本课只把它钉在「树负责跨节点段、环负责域内段」这一分工上。</p><p><span class="marginnote">数字实例：8 机每机 8 卡共 64 卡。不层次化，跨节点段要扛 64 份体积；先在节点内用 NVLink 收成每节点一份，跨节点只剩 8 份，最贵那一段的流量直接降到 \\(1/8\\)——层次化省的就是这段倍数。</span></p>',12)),(r(),E(A,null,{default:a(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%AF%8F%E5%8D%A1%E4%B8%80%E4%BB%BD%E5%BC%A0%E9%87%8F%22%5D%20--%3E%20R%5B%22Ring%3A%20reduce-scatter%20%E5%86%8D%20all-gather%22%5D%0A%20%20X%20--%3E%20T%5B%22Tree%3A%20reduce%20%E5%86%8D%20broadcast%22%5D%0A%20%20R%20--%3E%20Y%5B%22%E6%AF%8F%E5%8D%A1%E4%B8%80%E4%BB%BD%E5%92%8C%22%5D%0A%20%20T%20--%3E%20Y%0A%20%20R%20--%3E%20BW%5B%22%E5%A4%A7%E6%B6%88%E6%81%AF%20%2F%20%E5%AF%B9%E7%A7%B0%E9%93%BE%E8%B7%AF%22%5D%0A%20%20T%20--%3E%20LAT%5B%22%E5%B0%8F%E6%B6%88%E6%81%AF%20%2F%20%E5%B1%82%E6%AC%A1%E5%8C%96%E8%B7%A8%E8%8A%82%E7%82%B9%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("p",null,"NCCL 还可以把一次调用切成若干 chunk，环与树同时跑在不同 chunk 上（或先树后环）。用户几乎不手写环；要手写时，见引擎课里的自定义 allreduce，那是服务侧短消息的特化，训练梯度同步仍以库为准。",-1)),e[4]||(e[4]=l("h2",{id:"机制",tabindex:"-1"},[n("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=l("p",null,"时间粗写成 \\(T \\approx (k-1)\\alpha + \\frac{k-1}{k}n\\beta\\) 一类，环的 \\(k=N\\)，树的 \\(k\\) 与度数、是否双树有关。\\(\\alpha\\) 是启动延迟，\\(\\beta\\) 是字节的倒数带宽，\\(n\\) 是本地字节。大 \\(n\\) 时第二项主导，环的边负载均匀，每段只搬 \\(\\frac{N-1}{N}n\\)，busbw 可接近链路本身；小 \\(n\\) 时第一项主导，树少跳更赢。这就是后课带宽模型要定量的对象——本课先建立「两种 \\(k\\)」。",-1)),(r(),E(A,null,{default:a(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22%E6%B6%88%E6%81%AF%20n%20%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%5D%20--%3E%20SMALL%5B%22%E5%B0%8F%20n%EF%BC%9A%E5%90%AF%E5%8A%A8%E5%BB%B6%E8%BF%9F%20%CE%B1%20%E9%A1%B9%E4%B8%BB%E5%AF%BC%22%5D%0A%20%20MSG%20--%3E%20BIG%5B%22%E5%A4%A7%20n%EF%BC%9A%E5%AD%97%E8%8A%82%E9%A1%B9%20n%CE%B2%20%E4%B8%BB%E5%AF%BC%22%5D%0A%20%20SMALL%20--%3E%20T%5B%22%E6%A0%91%EF%BC%9A%E8%B7%B3%E6%95%B0%20O(log%20N)%EF%BC%8C%E5%90%8C%E6%AD%A5%E8%BD%AE%E5%B0%91%22%5D%0A%20%20BIG%20--%3E%20R%5B%22%E7%8E%AF%EF%BC%9A%E6%AF%8F%E8%BE%B9%E8%B4%9F%E8%BD%BD%202(N%E2%88%921)%2FN%EF%BC%8C%E5%9D%87%E5%8C%80%E6%89%93%E6%BB%A1%22%5D%0A%20%20T%20--%3E%20MIX%5B%22NCCL%20%E6%8C%89%20size%20%E5%88%87%E6%8D%A2%EF%BC%8C%E6%88%96%20chunk%20%E6%B7%B7%E8%B7%91%22%5D%0A%20%20R%20--%3E%20MIX%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p><span class="marginnote">为什么重要：环与树的加法顺序不同，而浮点加法没有结合律，同一个 All-Reduce 换算法后末几位会不一样。平时无害，但做逐位复现或追数值 bug 时，要先确认两次跑用的是同一算法、同一 chunk 切分，再去找别的原因。</span></p><p>环假设邻居之间有足够点对点带宽。NVLink 域、NVSwitch 平坦域满足；跨机柜若环的逻辑邻居落在同一条拥挤的叶子上行，逻辑环变成物理热点。树假设中间节点吃得下瞬时入度；层次化把入度关在节点内高带宽域，正是为了不让树的根长在百 Gb/s 网卡上。</p><p><span class="marginnote">「Ring 一定更快」是错的。8 卡 NVLink 上几 MB 的梯度，环几乎总是对的；64 卡以太网、几十字节的控制同步，树或折中更对。看 <code>nccl-tests</code> 的 busbw–size 曲线，不要只看算法名字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在不对称拓扑上强行单环：PCIe 与 NVLink 混用的节点，环会周期性地掉到慢边上。不要把营销里的「NVLink 全互连」当成跨柜也成立——柜外仍是网卡，All-Reduce 必须层次化。In-network 归约（如某些 InfiniBand SHARP）是第三张图：交换机做加，树的中间计算不占用 GPU；有则用，没有则回到主机侧环/树，不要假设每一代交换机都会加。</p><p>数值上，环是分段加，顺序与树不同，浮点和不完全结合律。BF16 / FP8 梯度通信时，这会变成可复现性差异，不是 bug。需要比特级一致时，固定算法与 chunk 大小，或在较高精度里归约。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>All-Reduce 的环实现达到带宽下界，步数随 \\(N\\) 线性；树实现跳数对数，适合延迟区。</li><li>大消息、对称链路用环；小消息、跨节点用层次化树。</li><li>环在物理上要求邻居带宽均匀；逻辑环画错轨，最慢边即 step time。</li><li>后课把 All-Reduce 拆成 reduce-scatter 与 all-gather，供 ZeRO 直接调用。</li><li>出处：带宽最优环的经典分析；NCCL 公开的 Ring / Tree 算法选择；层次化见 <a href="/llm/pretrain-comm">预训练通信</a>。</li></ul>',8))])}const F=d(c,[["render",p]]);export{k as __pageData,F as default};
